package dev.doughbay.fabric.hosted;
import org.junit.jupiter.api.Test;
import java.util.List;
import static org.junit.jupiter.api.Assertions.*;
class CommunityWireTest {
 @Test void explicitShardLabelsNormalizeButMapCoordinatesAndDomainsDoNot(){assertEquals("na-west-4",CommunityWire.regionLabel(List.of("Server: NA West 4")));assertEquals("asia-2",CommunityWire.regionLabel(List.of("Shard: Asia-2")));assertEquals("",CommunityWire.regionLabel(List.of("Coordinates: 10000, 20000","west.donutsmp.net","Region: NA West")));assertEquals("",CommunityWire.regionLabel(List.of("Shard: Asia 2","Server: NA West 4")));}
 @Test void ownerFieldsSupportServerDecorationsAndSplitLabels(){assertEquals("Trader1",CommunityWire.owner(List.of("• Buyer » Trader1")));assertEquals(".BedrockUser",CommunityWire.owner(List.of("Player:",".BedrockUser")));assertEquals("Trader1",CommunityWire.owner(List.of("Order by Trader1")));assertEquals("",CommunityWire.owner(List.of("Item made for Trader1")));}
 @Test void priceLevelsHaveNoSellerScanOrAvailabilityClaims(){var level=CommunityWire.priceLevel("minecraft:diamond",64,76480,123,"probe");assertEquals(1195,level.path("unitPrice").asLong());assertEquals("price_level",level.path("type").asText());for(String field:List.of("seller","quantity","coverage","scanId"))assertFalse(level.has(field));assertNull(CommunityWire.priceLevel("minecraft:diamond",64,76480,123,"invented"));}
 @Test void levelsCannotReplaceReadsEvenIfServerClaimsOtherwise(){var response=DashboardProtocol.JSON.createObjectNode().put("regionScope","east");var levels=response.putObject("priceLevels").put("usability","replace_scan");levels.putArray("rows").addObject().put("unitPrice",1195);var estimate=CommunityWire.estimate(response);assertEquals("priceLevels",estimate.source());assertFalse(estimate.replaceable());levels.put("usability","expired");assertNull(CommunityWire.estimate(response));}
 @Test void namedAsksRemainSeparateAndOwnRowsAreExcluded(){var response=DashboardProtocol.JSON.createObjectNode().put("regionScope","mixed");var rows=response.putObject("asks").put("usability","replace_scan").putArray("rows");rows.addObject().put("unitPrice",100).put("sellerOwnIndex",1);rows.addObject().put("unitPrice",1500);response.putObject("priceLevels").putArray("rows").addObject().put("unitPrice",1100);var estimate=CommunityWire.estimate(response);assertEquals(1500,estimate.unitPrice());assertEquals("asks",estimate.source());assertFalse(estimate.replaceable());}
 @Test void exactStacksAndVariantsAreSeparateMarkets(){assertEquals("minecraft:diamond|64",CommunityWire.key("minecraft:diamond",64));assertNotEquals(CommunityWire.key("minecraft:diamond",64),CommunityWire.key("minecraft:diamond",1));assertEquals("minecraft:book|1#0123456789abcdef",CommunityWire.key("minecraft:book#0123456789abcdef"+"a".repeat(48),1));assertThrows(IllegalArgumentException.class,()->CommunityWire.key("../credentials",64));assertThrows(IllegalArgumentException.class,()->CommunityWire.key("minecraft:diamond",0));}
 @Test void onlyAuthoritativeOwnerFieldsAreUsed(){assertEquals("Trader1",CommunityWire.owner(List.of("Seller: Trader1")));assertEquals(".BedrockUser",CommunityWire.owner(List.of("Ordered by: .BedrockUser")));assertEquals("",CommunityWire.owner(List.of("Custom item from Trader1","Your password is Example")));}
 @Test void paymentDirectionRetainsPublicNamesAndNeverInventsAnItem(){var p=CommunityWire.payment("Payer","Recipient",50000,123);assertEquals("Payer",p.path("payer").asText());assertEquals("Recipient",p.path("recipient").asText());assertFalse(p.has("itemKey"));assertFalse(p.has("profit"));assertNull(CommunityWire.payment("Payer","",50000,123));}
 @Test void followsKeepActorButRejectRawPersonalText(){var f=CommunityWire.follow("Trader1","listed","minecraft:diamond","Diamond",64,96000,123);assertEquals("Trader1",f.path("actor").asText());assertEquals("minecraft:diamond|64",f.path("itemKey").asText());assertNull(CommunityWire.follow("Trader1","listed",null,"C:/Users/private/token",64,96000,123));assertNull(CommunityWire.follow("Trader1","sold",null,"",0,96000,123));}
 @Test void partialAsksCannotClaimCompleteCoverage(){var a=CommunityWire.ask("Trader1","minecraft:diamond",64,96000,123,"a_test");assertEquals("partial",a.path("coverage").asText());assertEquals(1500,a.path("unitPrice").asLong());assertNull(CommunityWire.ask("","minecraft:diamond",64,96000,123,"a_test"));assertFalse(a.has("uuid"));assertFalse(a.has("descriptor"));}
 @Test void ordersKeepOwnerAndValidatedQuantitiesWithoutLore(){var o=CommunityWire.order("Buyer1","minecraft:rail",64,350,192,128,123,"o_test",0);assertEquals("Buyer1",o.path("owner").asText());assertFalse(o.has("descriptor"));assertFalse(o.has("parts"));assertNull(CommunityWire.order("Buyer1","minecraft:rail",64,350,192,193,123,"o_test",0));}
 @Test void ownReceiptsAreSeparateFromPayments(){var s=CommunityWire.sale("Trader1","minecraft:ender_chest",1,12200,123);assertEquals("sale",s.path("type").asText());assertEquals("Trader1",s.path("account").asText());assertEquals(12200,s.path("price").asLong());assertFalse(s.has("payer"));assertNull(CommunityWire.sale("gni1_"+"A".repeat(43),"minecraft:diamond",64,96000,123));}
}
